    const [state,trend,oauth,oauthRouting]=await Promise.all([request('/state'),request(`/trends?range=${APP.range}`).catch(()=>null),request('/oauth/accounts').catch(error=>({data:[],warning:error.message})),request('/oauth/routing').catch(()=>null)]);
    const serverRoutes=structuredClone(state.config?.routes||{}),serverFingerprint=Core.routeFingerprint(serverRoutes);
