function renderActiveView(preserveFocus=false){
  const focused=(APP.activeView==='routes'&&$('routeEditor').contains(document.activeElement))||(APP.activeView==='accounts'&&$('authAccounts').contains(document.activeElement))||(APP.activeView==='clients'&&$('clientModel')===document.activeElement);
  if(preserveFocus&&focused){if(APP.activeView==='routes')renderRouteChangeState(Core.routeValidation(APP.routeDraft,configuredAccounts()));return}
  if(APP.activeView==='usage')renderUsage();
  if(APP.activeView==='accounts')renderAccounts();
  if(APP.activeView==='routes')renderRoutes();
  if(APP.activeView==='clients')renderClients();
  if(APP.activeView==='diagnostics')renderAdapters();
}
function recordsInRange(){const cutoff=now()-(RANGE_MS[APP.range]||RANGE_MS['24h']);return(APP.data?.stats?.recent||[]).filter(record=>{const time=new Date(record.time).getTime();if(!Number.isFinite(time)||time<cutoff)return false;if(APP.accountFilter&&record.account_id!==APP.accountFilter)return false;return true})}
function usageEvidence(){const records=recordsInRange(),latencies=records.map(record=>finiteNumber(record.latency_ms)).filter(value=>value!==null),p95=percentile(latencies,.95),trendPoints=Array.isArray(APP.trend?.points)?APP.trend.points:null,filtered=!!APP.accountFilter;let calls,failed,source;if(!filtered&&trendPoints){calls=trendPoints.reduce((sum,point)=>sum+(Number(point.requests)||0),0);failed=trendPoints.reduce((sum,point)=>sum+(Number(point.failed)||0),0);source='trend'}else{calls=records.length;failed=records.filter(record=>!requestOK(record)).length;source='recent'}const successful=Math.max(0,calls-failed),successRate=calls?successful/calls*100:null;return{records,latencies,p95,calls,failed,successful,successRate,source}}
function requestOK(record){return Number(record.status)>=200&&Number(record.status)<400}
function quotaWindows(account){return Array.isArray(account?.quota_windows)?account.quota_windows.filter(window=>window&&window.kind):[]}
function quotaPercentage(window){const value=finiteNumber(window?.used_percentage);return value===null?null:Math.max(0,Math.min(100,value))}
function allQuotaObservations(){return APP.oauth.flatMap(account=>quotaWindows(account).map(window=>({account,window,used:quotaPercentage(window)})).filter(item=>item.used!==null))}
