function recordQuotaHistory(){try{const key='lite2api_quota_history_v1',history=JSON.parse(localStorage.getItem(key)||'[]'),timestamp=new Date().toISOString();for(const account of APP.oauth){for(const window of quotaWindows(account)){const used=quotaPercentage(window);if(used===null)continue;const id=`${account.id}|${window.kind}|${window.model||''}`;const latest=[...history].reverse().find(item=>item.id===id);if(!latest||now()-new Date(latest.time).getTime()>300000||Math.abs(latest.used-used)>.2)history.push({id,time:timestamp,used,account_id:account.id,provider:account.provider,label:window.model||window.label||window.kind})}}const cutoff=now()-30*86400000;APP.quotaHistory=history.filter(item=>new Date(item.time).getTime()>=cutoff).slice(-6000);localStorage.setItem(key,JSON.stringify(APP.quotaHistory))}catch{APP.quotaHistory=[]}}
function renderUsage(){if(!APP.data)return;const evidence=usageEvidence(),{records,successful,failed,successRate,latencies,p95,calls,source}=evidence,quota=tightestQuota(),recentLimit=APP.data.stats?.recent_limit||records.length;
 $('quotaKpi').textContent=quota?`${quota.used.toFixed(1)}%`:'—';$('quotaKpiNote').textContent=quota?`${quota.account.identity||quota.account.id} · ${quota.window.model||quota.window.label||quota.window.kind} · ${quota.window.reset_at?relativeTime(quota.window.reset_at)+'重置':'重置时间未知'}`:(APP.oauthError?'认证适配器不可读':'暂无上游额度观测');
 $('callsKpi').textContent=number(calls);$('callsKpiNote').textContent=source==='trend'?`${RANGE_LABEL[APP.range]}完整聚合 · ${number(failed)} 次失败`:`最近请求样本 · 最多 ${number(recentLimit)} 条`;
 $('successKpi').textContent=successRate===null?'—':`${successRate.toFixed(2)}%`;$('successKpiNote').textContent=calls?`${number(successful)} 成功 / ${number(failed)} 失败${source==='recent'?' · 样本口径':''}`:'没有真实请求';
 $('latencyKpi').textContent=p95===null?'—':`${number(Math.round(p95))} ms`;$('latencyKpiNote').textContent=latencies.length?`最近 ${number(latencies.length)} 个完成请求样本`:'没有延迟样本';
 const fastest=connectionStats().filter(item=>item.samples>0).sort((a,b)=>a.avg-b.avg)[0],unhealthy=connectionStats().filter(item=>item.failures>0).sort((a,b)=>b.failureRate-a.failureRate)[0];
 const clauses=[];if(quota)clauses.push(`${quota.account.identity||quota.account.id} 的 ${quota.window.model||quota.window.label||'额度'} 已用 ${quota.used.toFixed(1)}%`);if(calls)clauses.push(`${RANGE_LABEL[APP.range]}调用 ${number(calls)} 次，成功率 ${successRate.toFixed(2)}%${source==='recent'?'（最近样本）':''}`);if(fastest)clauses.push(`${fastest.name} 当前最快`);if(unhealthy&&unhealthy.failureRate>=.05)clauses.push(`${unhealthy.name} 需要关注`);$('usageHeadline').textContent=clauses.length?clauses.join('；')+'。':'当前还没有足够的真实使用数据。';
 renderUsageFilters();renderInsights({records,quota,fastest,unhealthy,p95});renderQuotaBoard();renderQuality();renderRequests();drawUsageChart();}
function renderUsageFilters(){const select=$('usageAccountFilter'),selected=APP.accountFilter,accounts=APP.data?.accounts||[];select.innerHTML='<option value="">全部渠道</option>'+accounts.map(account=>`<option value="${escapeHTML(account.id)}">${escapeHTML(account.name||account.id)}</option>`).join('');if(accounts.some(account=>account.id===selected))select.value=selected;else APP.accountFilter=''}
function connectionStats(){const configured=APP.data?.config?.accounts||[],runtime=APP.data?.accounts||[],recent=APP.data?.stats?.recent||[];return configured.map(config=>{const live=runtime.find(item=>item.id===config.id)||{},rows=recent.filter(row=>row.account_id===config.id),latencies=rows.map(row=>finiteNumber(row.latency_ms)).filter(value=>value!==null),failures=rows.filter(row=>!requestOK(row)).length,liveAverage=finiteNumber(live.average_latency_ms);return{id:config.id,name:config.name||config.id,config,live,rows,samples:rows.length,failures,failureRate:rows.length?failures/rows.length:0,avg:latencies.length?latencies.reduce((sum,value)=>sum+value,0)/latencies.length:liveAverage??Infinity,p95:percentile(latencies,.95)}})}
function renderInsights(context){const items=[];if(context.quota){const tone=quotaTone(context.quota.used);items.push({label:'额度',text:`${context.quota.account.identity||context.quota.account.id} 的 ${context.quota.window.model||context.quota.window.label||'窗口'} 最紧张，已用 ${context.quota.used.toFixed(1)}%。`,tone})}else items.push({label:'额度',text:'暂无可计算的百分比额度；未知不会按 0% 展示。'});if(context.fastest)items.push({label:'速度',text:`${context.fastest.name} 最近平均 ${number(Math.round(context.fastest.avg))} ms，是有样本渠道中最快的一条。`});else items.push({label:'速度',text:'尚无足够的完成请求样本。'});if(context.unhealthy&&context.unhealthy.failures)items.push({label:'质量',text:`${context.unhealthy.name} 最近 ${context.unhealthy.failures}/${context.unhealthy.samples} 次失败，建议执行三轮直测。`,tone:context.unhealthy.failureRate>=.2?'bad':'warn'});else items.push({label:'质量',text:'最近样本没有集中失败；可按需执行三轮直测。'});$('usageInsights').innerHTML=items.map(item=>`<div class="insight-item ${item.tone||''}"><span>${escapeHTML(item.label)}</span><strong>${escapeHTML(item.text)}</strong></div>`).join('')}
function quotaWindowHTML(window){const used=quotaPercentage(window),label=window.model||window.label||window.kind,reset=window.reset_at?relativeTime(window.reset_at)+'重置':'重置时间未知',observed=window.observed_at?relativeTime(window.observed_at)+'观测':'观测时间未知',source=window.source||'上游未标注',icon=modelIconHTML(label,'inline-model-icon');if(used===null){const remaining=finiteNumber(window.remaining),value=remaining!==null?`${number(remaining)} ${window.unit||''}`.trim():window.status==='cooldown'?'冷却中':window.status==='exhausted'?'已耗尽':'已观测';return`<div class="quota-unknown"><div class="quota-unknown-head">${icon}<strong>${escapeHTML(label)}</strong><span>· ${escapeHTML(value)}</span></div><small>${escapeHTML(reset)} · ${escapeHTML(observed)} · ${escapeHTML(source)}</small></div>`}const tone=quotaTone(used);return`<div class="quota-window ${tone}"><div class="quota-window-head"><span class="quota-model-label">${icon}${escapeHTML(label)}</span><strong>${used.toFixed(1)}%</strong></div><div class="quota-bar"><i style="width:${used}%"></i></div><span class="quota-meta">${escapeHTML(reset)} · ${escapeHTML(observed)} · ${escapeHTML(source)}</span></div>`}
function renderQuotaBoard(){const rows=APP.oauth;if(!rows.length){$('quotaBoard').innerHTML=`<div class="empty-copy"><strong>${APP.oauthError?'认证额度暂时不可读':'还没有认证账号'}</strong><br>${APP.oauthError?'认证服务恢复后会自动刷新；其他使用数据不受影响。':'添加 OAuth 或订阅账号后显示真实额度。'}</div>`;return}$('quotaBoard').innerHTML=rows.map(account=>{const key=providerKey(account.provider),status=accountStatus(account),windows=quotaWindows(account),windowHTML=windows.length?windows.slice(0,4).map(quotaWindowHTML).join(''):'<div class="quota-unknown">等待上游返回额度；不会显示伪造的 0%。</div>';return`<article class="quota-account"><div class="quota-identity">${providerIconHTML(key)}<div><strong>${escapeHTML(account.identity||'已保存凭据')}</strong><span>${escapeHTML(PROVIDER_LABEL[key]||account.provider)} · ${escapeHTML(account.plan||'套餐未知')}</span></div></div><div class="quota-windows">${windowHTML}</div><div class="quota-status"><span class="status-pill ${status.tone}">${escapeHTML(status.label)}</span><small>${escapeHTML(account.updated_at?relativeTime(account.updated_at)+'更新':'更新时间未知')}</small></div></article>`}).join('')}
