function qualityConclusion(result){if(!result)return{label:'未测试',tone:'neutral'};if(result.running)return{label:'测试中',tone:'neutral'};const successes=result.rounds.filter(round=>round.ok).length;if(!successes)return{label:'不可用',tone:'bad'};const values=result.rounds.filter(round=>round.ok).map(round=>round.latency_ms),avg=values.reduce((a,b)=>a+b,0)/values.length,spread=values.length>1?(Math.max(...values)-Math.min(...values))/Math.max(1,avg):0;if(successes<result.rounds.length)return{label:'有失败',tone:'warn'};if(spread>.45)return{label:'波动较大',tone:'warn'};return{label:'稳定',tone:''}}
