    const roundLabels=result?result.rounds.map((round,index)=>`第 ${index+1} 轮${round.ok?`成功，${round.latency_ms} ms`:`失败，${round.error||'未知错误'}`}`):[];
    const run=result?result.rounds.map(round=>`<i class="${round.ok?'good':'bad'}" title="${escapeHTML(round.ok?round.latency_ms+' ms':round.error||'失败')}" aria-hidden="true"></i>`).join(''):'<i aria-hidden="true"></i><i aria-hidden="true"></i><i aria-hidden="true"></i>';
