function configuredAccount(id){return(APP.data?.config?.accounts||[]).find(account=>account.id===id)}
function accountTestModel(account){
  const routed=Object.entries(APP.data?.config?.routes||{}).flatMap(([alias,raw])=>{
    const route=Core.normalizeRoute(raw),usesAccount=route.all_accounts?account?.enabled!==false:route.targets.some(target=>target.account===account?.id);
    if(!usesAccount)return[];
    if(route.legacy)return[route.upstream_model||account?.model_map?.[alias]||alias];
    return route.targets.filter(target=>target.account===account?.id).map(target=>target.model).filter(Boolean);
  })[0];
  return(account?.models||[]).find(model=>model&&model!=='*')||account?.capabilities?.[0]?.upstream_model||routed||account?.capabilities?.[0]?.model||'';
}
async function runQuality(id){
  const account=configuredAccount(id);if(!account||APP.qualityRunning.has(id))return;
  const model=accountTestModel(account);if(!model){toast('该连接没有可测试模型',true);return}
  const connectionFingerprint=accountFingerprint(account),result={running:true,rounds:[],tested_at:new Date().toISOString(),model,connection_fingerprint:connectionFingerprint};
  APP.qualityRunning.add(id);APP.quality.set(id,result);renderQuality();
  try{
    for(let index=0;index<3;index++){
      try{const response=await request('/prompt-test',{method:'POST',timeout:125000,body:JSON.stringify({account_id:id,model,messages:[{role:'user',content:'质量探针：只回复 OK'}],temperature:0,max_tokens:16})}),content=JSON.stringify(response.response||{});result.rounds.push({ok:content.length>2,latency_ms:Number(response.latency_ms)||0,request_id:response.request_id||'',model:response.upstream_model||model})}
      catch(error){result.rounds.push({ok:false,error:error.message,status:error.status||0})}
      APP.quality.set(id,result);renderQuality();if(index<2)await sleep(180);
    }
    result.running=false;result.tested_at=new Date().toISOString();APP.quality.set(id,result);saveQuality();toast(`${account.name||id} 三轮直测完成`);
  }finally{APP.qualityRunning.delete(id);renderQuality()}
}
async function runAllQuality(){const button=$('testAllChannels');button.disabled=true;try{for(const account of APP.data?.config?.accounts||[]){if(account.enabled!==false&&accountTestModel(account))await runQuality(account.id)}}finally{button.disabled=false}}
function channelChatAccounts(){return(APP.data?.config?.accounts||[]).filter(account=>account.enabled!==false&&Core.channelChatSupported(account))}
function channelChatErrorText(error){const upstream=error?.payload?.upstream;let detail='';if(typeof upstream==='string')detail=upstream;else if(upstream&&typeof upstream==='object')detail=upstream.error?.message||upstream.message||'';return detail&&detail!==error.message?`${error.message}：${detail}`:error.message||'渠道聊天测试失败'}
