function renderChannelChat(){const container=$('channelChatMessages'),items=[...APP.channelChatMessages];if(APP.channelChatPending)items.push({role:'pending',content:'上游正在生成回复…',at:new Date().toISOString()});container.setAttribute('aria-busy',String(APP.channelChatPending));if(!items.length){container.innerHTML='<div class="channel-chat-empty"><strong>开始一次真实渠道对话</strong><span>回复会显示实际模型、耗时、Token 和请求 ID。</span></div>';return}container.innerHTML=items.map(message=>{const role=message.role,label=role==='user'?'你':role==='assistant'?'渠道回复':role==='error'?'请求失败':'等待中',meta=[];if(role==='assistant'){if(message.upstream_model)meta.push(`上游 ${message.upstream_model}`);if(Number.isFinite(message.latency_ms))meta.push(`${number(message.latency_ms)} ms`);if(message.total_tokens!==null&&message.total_tokens!==undefined)meta.push(`Token ${number(message.total_tokens)}${message.input_tokens!==null&&message.output_tokens!==null?`（${number(message.input_tokens)} + ${number(message.output_tokens)}）`:''}`);if(message.finish_reason)meta.push(message.finish_reason);if(message.request_id)meta.push(`请求 ${message.request_id}`)}const raw=message.raw?`<details><summary>查看原始响应</summary><pre>${escapeHTML(message.raw)}</pre></details>`:'';return`<article class="channel-chat-message ${escapeHTML(role)}"><header><span>${label}</span><time>${new Date(message.at||Date.now()).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</time></header><div class="channel-chat-content">${escapeHTML(message.content)}</div>${meta.length?`<footer>${meta.map(value=>`<span>${escapeHTML(value)}</span>`).join('')}</footer>`:''}${raw}</article>`}).join('');requestAnimationFrame(()=>{container.scrollTop=container.scrollHeight})}
function syncChannelChatTarget(resetModel=false){const account=configuredAccount($('channelChatAccount').value),modelInput=$('channelChatModel');APP.channelChatAccount=account?.id||'';const models=Core.channelChatModels(account);$('channelChatModels').innerHTML=models.map(model=>`<option value="${escapeHTML(model)}"></option>`).join('');if(resetModel||!modelInput.value.trim())modelInput.value=accountTestModel(account)||models[0]||'';const protocol=account?.type==='anthropic'?'Anthropic Messages':'OpenAI Chat Completions';$('channelChatTarget').textContent=account?`直连 ${account.name||account.id} · ${protocol} · ${modelInput.value.trim()||'请填写模型'}。测试会产生真实上游调用并消耗额度。`:'当前没有可聊天测试的已启用渠道。'}
