function resetChannelChat(){if(APP.channelChatPending)return;APP.channelChatGeneration++;APP.channelChatMessages=[];renderChannelChat();$('channelChatInput').value='';$('channelChatInput').focus()}
function openChannelChat(id=''){const accounts=channelChatAccounts();if(!accounts.length){toast('当前没有支持聊天的已启用渠道',true);return}cancelChannelChat();APP.channelChatGeneration++;APP.channelChatMessages=[];APP.channelChatPending=false;APP.channelChatController=null;const selected=accounts.find(account=>account.id===id)||accounts[0],select=$('channelChatAccount');select.innerHTML=accounts.map(account=>`<option value="${escapeHTML(account.id)}">${escapeHTML(account.name||account.id)} · ${escapeHTML(account.id)}</option>`).join('');select.value=selected.id;$('channelChatModel').value='';$('channelChatSystem').value='';$('channelChatTemperature').value='';$('channelChatMaxTokens').value='';$('channelChatInput').value='';setChannelChatBusy(false);syncChannelChatTarget(true);renderChannelChat();openDialog('channelChatDialog');setTimeout(()=>$('channelChatInput').focus(),0)}
function boundedChannelChatMessages(system){let history=APP.channelChatMessages.filter(message=>['user','assistant'].includes(message.role)&&message.included!==false).map(message=>({role:message.role,content:message.content})),limit=system?63:64;history=history.slice(-limit);if(history[0]?.role==='assistant')history.shift();let messages=system?[{role:'system',content:system},...history]:history;while(messages.length>1&&new TextEncoder().encode(JSON.stringify(messages)).length>240*1024){history.shift();if(history[0]?.role==='assistant')history.shift();messages=system?[{role:'system',content:system},...history]:history}return messages}
async function sendChannelChat(event){event.preventDefault();if(APP.channelChatPending)return;const account=configuredAccount($('channelChatAccount').value),model=$('channelChatModel').value.trim(),content=$('channelChatInput').value.trim(),temperatureText=$('channelChatTemperature').value.trim(),maxTokensText=$('channelChatMaxTokens').value.trim();if(!account||account.enabled===false||!Core.channelChatSupported(account)){toast('请选择支持聊天的已启用渠道',true);return}if(!model){toast('请选择或填写测试模型',true);$('channelChatModel').focus();return}if(!content){toast('请输入要发送的消息',true);$('channelChatInput').focus();return}const temperature=temperatureText===''?null:Number(temperatureText),maxTokens=maxTokensText===''?0:Number(maxTokensText);if(temperature!==null&&(!Number.isFinite(temperature)||temperature<0||temperature>2)){toast('Temperature 必须在 0–2 之间',true);return}if(!Number.isInteger(maxTokens)||maxTokens<0||maxTokens>32768){toast('最大输出 Token 必须是 0–32768 的整数',true);return}const userMessage={role:'user',content,included:true,at:new Date().toISOString()};APP.channelChatMessages.push(userMessage);$('channelChatInput').value='';const generation=++APP.channelChatGeneration,controller=new AbortController();APP.channelChatController=controller;setChannelChatBusy(true);renderChannelChat();try{const body={account_id:account.id,model,messages:boundedChannelChatMessages($('channelChatSystem').value.trim())};if(temperature!==null)body.temperature=temperature;if(maxTokens>0)body.max_tokens=maxTokens;const result=await request('/prompt-test',{method:'POST',timeout:125000,signal:controller.signal,body:JSON.stringify(body)});if(generation!==APP.channelChatGeneration)return;const parsed=Core.channelChatResponse(result.response);if(!parsed.text)userMessage.included=false;APP.channelChatMessages.push({role:'assistant',content:parsed.text||'上游请求成功，但响应中没有可显示的文本内容。',included:!!parsed.text,at:new Date().toISOString(),upstream_model:result.upstream_model||parsed.model||model,latency_ms:Number(result.latency_ms),input_tokens:parsed.input_tokens,output_tokens:parsed.output_tokens,total_tokens:parsed.total_tokens,finish_reason:parsed.finish_reason,request_id:result.request_id||parsed.response_id,raw:channelChatRawPreview(result.response)});toast(`${account.name||account.id} 回复成功 · ${number(result.latency_ms)} ms`)}catch(error){if(generation!==APP.channelChatGeneration)return;userMessage.included=false;APP.channelChatMessages.push({role:'error',content:channelChatErrorText(error),included:false,at:new Date().toISOString()})}finally{if(generation===APP.channelChatGeneration){APP.channelChatController=null;setChannelChatBusy(false);renderChannelChat();$('channelChatInput').focus()}}}
function chartBucketsFromRecords(metric){const records=recordsInRange(),range=RANGE_MS[APP.range],bucket=APP.range==='24h'?3600000:APP.range==='7d'?6*3600000:24*3600000,start=Math.floor((now()-range)/bucket)*bucket,count=Math.ceil(range/bucket)+1,buckets=Array.from({length:count},(_,index)=>({time:start+index*bucket,records:[]}));for(const record of records){const time=new Date(record.time).getTime(),index=Math.floor((time-start)/bucket);if(index>=0&&index<buckets.length)buckets[index].records.push(record)}return buckets.map(bucketItem=>{const rows=bucketItem.records,latencies=rows.map(row=>finiteNumber(row.latency_ms)).filter(value=>value!==null);let value=null;if(rows.length&&metric==='requests')value=rows.length;if(rows.length&&metric==='tokens')value=Core.meteredTokenTotal(rows);if(metric==='success')value=rows.length?rows.filter(requestOK).length/rows.length*100:null;if(metric==='latency')value=percentile(latencies,.95);return{time:bucketItem.time,value,count:rows.length}})}
function chartSeries(){if(APP.metric==='quota'){const cutoff=now()-(RANGE_MS[APP.range]||RANGE_MS['24h']),items=APP.quotaHistory.filter(item=>new Date(item.time).getTime()>=cutoff&&(!APP.accountFilter||item.account_id===APP.accountFilter));let target='';if(APP.accountFilter){target=items[0]?.id||''}else{const quota=tightestQuota();target=quota?`${quota.account.id}|${quota.window.kind}|${quota.window.model||''}`:items[0]?.id||''}return items.filter(item=>!target||item.id===target).map(item=>({time:new Date(item.time).getTime(),value:item.used,count:1,label:item.label})).sort((a,b)=>a.time-b.time)}if(APP.accountFilter||['tokens','success'].includes(APP.metric))return chartBucketsFromRecords(APP.metric);if(APP.trend?.points?.length&&['requests','latency'].includes(APP.metric)){return APP.trend.points.map(point=>({time:new Date(point.time).getTime(),value:APP.metric==='requests'?Number(point.requests):point.p95_latency_ms===null?null:Number(point.p95_latency_ms),count:Number(point.requests)||0})).filter(point=>Number.isFinite(point.time))}return chartBucketsFromRecords(APP.metric)}
function metricLabel(){return({requests:'调用次数',tokens:'Token',success:'成功率',latency:'P95 响应耗时',quota:'额度已用比例'})[APP.metric]}
function formatMetricValue(value){if(value===null||!Number.isFinite(Number(value)))return'—';if(['success','quota'].includes(APP.metric))return`${Number(value).toFixed(1)}%`;if(APP.metric==='latency')return`${number(Math.round(value))} ms`;return number(Math.round(value))}
