  const minTime=Math.min(...series.map(point=>point.time)),maxTime=Math.max(...series.map(point=>point.time)),values=valid.map(point=>Number(point.value)),minValue=['success','quota'].includes(APP.metric)?0:Math.min(0,...values),maxValue=['success','quota'].includes(APP.metric)?100:Math.max(1,...values)*1.08;
  ctx.font='11px '+getComputedStyle(document.body).fontFamily;ctx.textBaseline='middle';
  for(let row=0;row<5;row++){const ratio=row/4,y=pad.top+ratio*plotH,value=maxValue-(maxValue-minValue)*ratio;ctx.strokeStyle='#ececef';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad.left,y);ctx.lineTo(width-pad.right,y);ctx.stroke();ctx.fillStyle='#67676e';ctx.textAlign='right';ctx.fillText(formatAxisMetricValue(value,maxValue-minValue),pad.left-7,y)}
  const points=[];let drawing=false;ctx.beginPath();
  for(const point of series){if(point.value===null||!Number.isFinite(Number(point.value))){drawing=false;continue}const x=pad.left+(point.time-minTime)/Math.max(1,maxTime-minTime)*plotW,y=pad.top+(maxValue-Number(point.value))/Math.max(1,maxValue-minValue)*plotH;points.push({...point,x,y});if(drawing)ctx.lineTo(x,y);else{ctx.moveTo(x,y);drawing=true}}
  ctx.strokeStyle='#1976d2';ctx.lineWidth=2.4;ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke();ctx.fillStyle='#1976d2';
  for(const point of points){ctx.beginPath();ctx.arc(point.x,point.y,points.length>80?1.3:2.2,0,Math.PI*2);ctx.fill()}
  ctx.fillStyle='#67676e';ctx.textBaseline='bottom';ctx.textAlign='left';const formatAxis=time=>new Date(time).toLocaleString('zh-CN',APP.range==='24h'?{hour:'2-digit',minute:'2-digit'}:{month:'2-digit',day:'2-digit'});ctx.fillText(formatAxis(minTime),pad.left,height-2);ctx.textAlign='right';ctx.fillText(formatAxis(maxTime),width-pad.right,height-2);APP.chartPoints=points;
  if(APP.chartIndex>=points.length)APP.chartIndex=points.length-1;if(document.activeElement===canvas&&APP.chartIndex>=0)showChartPoint(points[APP.chartIndex],APP.chartIndex);
