function chartPointDescription(point){return`${metricLabel()} ${formatMetricValue(point.value)}，${formatTime(point.time)}${point.count!==undefined?`，样本 ${number(point.count)}`:''}`}
function showChartPoint(point,index){if(!point)return;const canvas=$('usageChart'),tooltip=$('chartTooltip'),rect=canvas.getBoundingClientRect();APP.chartIndex=index;tooltip.hidden=false;tooltip.innerHTML=`<strong>${escapeHTML(metricLabel())} ${escapeHTML(formatMetricValue(point.value))}</strong><br>${escapeHTML(formatTime(point.time))}${point.count!==undefined?`<br>样本 ${number(point.count)}`:''}`;tooltip.style.left=canvas.offsetLeft+Math.min(rect.width-150,Math.max(8,point.x+10))+'px';tooltip.style.top=canvas.offsetTop+Math.max(8,point.y-24)+'px';$('chartA11ySummary').textContent=`第 ${index+1} / ${APP.chartPoints.length} 个数据点：${chartPointDescription(point)}`}
