function renderSetupToken(provider){setOnboardingStep('action');$('providerActionTitle').textContent='导入 Claude Setup Token';$('providerActionDescription').textContent='格式预检通过后会直接写入认证池。';const panel=$('providerActionPanel');panel.innerHTML=`<label>Claude Setup Token<input id="setupTokenInput" type="password" autocomplete="off" placeholder="粘贴 setup-token"></label><p class="field-help">凭据不会写入 Lite2API 连接配置；认证池会通过稳定连接供模型路由使用。</p><button id="importSetupToken" class="primary" type="button">验证并添加</button>`;$('importSetupToken').addEventListener('click',async()=>{const token=$('setupTokenInput').value.trim();if(!token){toast('请填写 Setup Token',true);return}const data={type:'sub2api-data',version:1,accounts:[{id:`claude-setup-${Date.now()}`,name:'Claude Setup Token',platform:provider,type:'oauth',credentials:{setup_token:token}}]};try{const preview=await request('/accounts/import',{method:'POST',body:JSON.stringify({data,mode:'skip',dry_run:true})});if((preview.oauth_failed||0)>0)throw new Error(preview.errors?.[0]?.message||'Setup Token 预检失败');await request('/accounts/import',{method:'POST',body:JSON.stringify({data,mode:'skip',dry_run:false})});closeDialog('addAccountDialog');await refreshAll(true,true);finishCredentialOnboarding({kind:'credential',provider,connection_id:findOAuthPoolConnection()?.id||'',title:'Setup Token 已加入认证池'})}catch(error){toast(error.message,true)}})}
function normalizeCookie(value){let pairs=[];try{const parsed=JSON.parse(value);if(Array.isArray(parsed))pairs=parsed.filter(item=>item?.name&&item.value!==undefined).map(item=>[item.name,item.value])}catch{}if(!pairs.length&&value.includes('\t'))pairs=value.split(/\r?\n/).map(line=>line.trim()).filter(line=>line&&!line.startsWith('#')).map(line=>line.split('\t')).filter(parts=>parts.length>=7).map(parts=>[parts[5],parts[6]]);if(!pairs.length)pairs=value.split(';').map(part=>{const at=part.indexOf('=');return at>0?[part.slice(0,at).trim(),part.slice(at+1).trim()]:null}).filter(Boolean);return[...new Map(pairs).entries()].map(([name,val])=>`${name}=${val}`).join('; ')}
