    let fingerprint=accountFingerprint(account),criticalChanged=fingerprint!==APP.manualOriginalFingerprint;
    const needsTest=Core.connectionTestRequired({editing,enabled:account.enabled,currentFingerprint:fingerprint,originalFingerprint:APP.manualOriginalFingerprint,testedFingerprint:APP.manualTestFingerprint});
    if(needsTest){button.textContent='正在测试…';if(!await testManualAccount())return;account=accountPayloadFromForm();fingerprint=accountFingerprint(account);criticalChanged=fingerprint!==APP.manualOriginalFingerprint}
    button.textContent='正在保存…';await request('/accounts',{method:'PUT',body:JSON.stringify(account)});if(criticalChanged){APP.quality.delete(account.id);saveQuality()}
    closeDialog('manualAccountDialog');await refreshAll(true,true);const saved=configuredAccount(account.id)||account,models=Core.directModels(saved);
    if(!editing&&saved.enabled!==false&&models.length){showView('routes',true);openRouteCreate(saved.id,models[0]);toast('连接已保存；确认对外模型名即可启用路由')}
    else{showView('accounts',true);setAccountTab('connections');toast(editing?'连接已更新并热加载':'连接已保存并热加载')}
