function openImportDialog(){APP.importFiles=[];APP.importData=null;APP.importPreview=null;$('importFilesInput').value='';$('importFileList').innerHTML='';$('importTotals').innerHTML='<span>等待预检查</span>';$('importPreviewRows').innerHTML='<div class="empty-copy">选择文件后执行预检查</div>';$('applyImport').disabled=true;openDialog('importDialog')}
