function normalizeImportObject(value){if(Array.isArray(value))return{type:'lite2api-data',version:1,accounts:value,proxies:[]};if(value?.data&&!value.accounts)value=value.data;if(value?.accounts)return{type:value.type||'lite2api-data',version:value.version??1,exported_at:value.exported_at,accounts:value.accounts,proxies:value.proxies||[]};if(value&&typeof value==='object')return{type:'lite2api-data',version:1,accounts:[value],proxies:[]};throw new Error('不是可识别的账号 JSON')}
