  const credentialTarget=String(account?.adapter_id||'').toLowerCase()==='cli-proxy-api',credentials=oauthCredentialsForConnection(account),credentialMissing=target.credential&&!credentials.some(item=>item.id===target.credential)?`<option value="${escapeHTML(target.credential)}" selected>${escapeHTML(credentialDisplay(target.credential))}（当前不可见）</option>`:'',credentialField=credentialTarget?`<label>认证账号<select data-target-field="credential"><option value="">自动账号池</option>${credentialMissing}${credentials.map(item=>{const status=accountStatus(item),selected=item.id===target.credential;return`<option value="${escapeHTML(item.id)}" ${selected?'selected':''} ${item.disabled?'disabled':''}>${escapeHTML(item.identity||item.id)} · ${escapeHTML(status.label)}</option>`}).join('')}</select><span class="target-resolution ${target.credential?'':'warn'}">${target.credential?'只使用该账号；失败后进入下一目标':'由认证池自动选号并在池内重试'}</span></label>`:'';
